begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(17678489401311414)
,p_name=>'OKTA_SSO'
,p_scheme_type=>'NATIVE_SOCIAL'
,p_attribute_01=>wwv_flow_imp.id(17678099510298925)
,p_attribute_02=>'OPENID_CONNECT'
,p_attribute_03=>'https://trial-3870463-admin.okta.com/.well-known/openid-configuration'
,p_attribute_07=>'profile'
,p_attribute_09=>'name'
,p_attribute_10=>'sub, profile'
,p_attribute_11=>'N'
,p_attribute_13=>'Y'
,p_attribute_14=>'G_SUB'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'PROCEDURE p_post_processing ',
'IS',
'    l_clob          CLOB;',
'    j            APEX_JSON.t_values;',
'    l_group_names apex_t_varchar2;',
'    l_api_key_c  CONSTANT VARCHAR2(256) DEFAULT ''00vx1MgsJ4g2ybqFqkdIkjXG0cD1h-EbyEpeWea2pd'';',
'    l_org_url_c  CONSTANT VARCHAR2(256) DEFAULT ''https://trial-3870463-admin.okta.com'';',
'BEGIN',
'    apex_web_service.set_request_headers(',
'        p_name_01        => ''Content-Type'',',
'        p_value_01       => ''application/json'',',
'        p_name_02        => ''Accept'',',
'        p_value_02       => ''application/json'',',
'        p_name_03        => ''Authorization'',',
'        p_value_03       => ''SSWS '' || l_api_key_c',
'         );',
'    l_clob := apex_web_service.make_rest_request(',
'        p_url => l_org_url_c || ''/api/v1/users/maximillian.grossman@oracle.com/groups'',',
'        p_http_method => ''GET'');',
'     APEX_JSON.PARSE(p_values => j, p_source => l_clob);',
'   FOR i IN 1 .. APEX_JSON.GET_COUNT(p_path=> ''.'', p_values=> j) ',
'   LOOP',
'        -- add all group names to l_group_names',
'         apex_string.push (',
'                  p_table => l_group_names,',
'                  p_value => apex_json.get_varchar2(p_path=>''[%d].profile.name'',p0=> i,p_values=>j));     ',
'   END LOOP;',
'    -- save group names in session',
'    apex_authorization.enable_dynamic_groups (',
'        p_group_names => l_group_names );',
'END p_post_processing;'))
,p_invalid_session_type=>'LOGIN'
,p_logout_url=>'https://ijegqeyui1cwvrq-cidemos.adb.us-ashburn-1.oraclecloudapps.com/ords/r/cidemos/okta-sso/home'
,p_post_auth_process=>'p_post_processing '
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>45040856961809
);
end;
